PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?film ?director ?birthDate WHERE {
  VALUES ?film { 
    <http://dbpedia.org/resource/Return_to_Return_to_Nuke_'Em_High_AKA_Volume_2> 
    <http://dbpedia.org/resource/Zameen_(2003_film)> 
  }

  # director (prefer dbp:director)
  OPTIONAL { ?film dbp:director ?director . }
  OPTIONAL { ?film dbo:director ?director . }
  FILTER (BOUND(?director))

  # director birth date (prefer dbp:birthDate)
  OPTIONAL { ?director dbp:birthDate ?dbpBirth . }
  OPTIONAL { ?director dbo:birthDate ?dboBirth . }
  BIND (COALESCE(?dbpBirth, ?dboBirth) AS ?birthDate)
}
LIMIT 100

